    p->velocity.y = -p->velocity.y * elasticity;
}

// Ceiling collision (y = 2*boxWidth)
if (p->position.y > 2.0f * boxWidth - h) {
    p->position.y = 2.0f * boxWidth - h;
    p->velocity.y = -p->velocity.y * elasticity;
}

// Left wall collision (x = 0)
if (p->position.x < h) {
    p->position.x = h;
    p->velocity.x = -p->velocity.x * elasticity;
}

// Right wall collision (x = 2*boxWidth)
if (p->position.x > 2.0f * boxWidth - h) {
    p->position.x = 2.0f * boxWidth - h;
    p->velocity.x = -p->velocity.x * elasticity;
}

// Back wall collision (z = 0)
if (p->position.z < h) {
    p->position.z = h;
    p->velocity.z = -p->velocity.z * elasticity;
}

// Front wall collision (z = 2*boxWidth)
if (p->position.z > 2.0f * boxWidth - h) {
    p->position.z = 2.0f * boxWidth - h;
    p->velocity.z = -p->velocity.z * elasticity;
}
